package com.bank.strategies.model;

// Which version serves the request, and whether its response is used.
public class RouteDecision {
    private final Version servedBy;        // who produces the user-facing response
    private final Version mirroredTo;      // shadow target, or null if none
    private final boolean mirrorDiscarded; // true when the shadow response is thrown away

    public RouteDecision(Version servedBy, Version mirroredTo, boolean mirrorDiscarded) {
        this.servedBy = servedBy;
        this.mirroredTo = mirroredTo;
        this.mirrorDiscarded = mirrorDiscarded;
    }

    public Version getServedBy() { return servedBy; }
    public Version getMirroredTo() { return mirroredTo; }
    public boolean isMirrorDiscarded() { return mirrorDiscarded; }
}
