package com.bank.strategies.router;

import com.bank.strategies.model.RouteDecision;
import com.bank.strategies.model.Version;

// Sends a fixed percentage of real traffic to NEW; the rest to OLD.
public class CanaryRouter implements TrafficRouter {
    private final int percentage;

    public CanaryRouter(int percentage) { this.percentage = percentage; }

    @Override
    public RouteDecision route(int requestNumber) {
        // Every Nth request goes to NEW based on the percentage.
        boolean toNew = (requestNumber % 100) < percentage;
        return new RouteDecision(toNew ? Version.NEW : Version.OLD, null, false);
    }

    @Override public String name() { return "Canary(" + percentage + "%)"; }
    @Override public String rollbackSpeed() {
        return "fast — only " + percentage + "% exposed, route them back to OLD";
    }
}
