package com.bank.strategies.router;

import com.bank.strategies.model.RouteDecision;
import com.bank.strategies.model.Version;

// All traffic goes to whichever environment is "live". Flip is instant.
public class BlueGreenRouter implements TrafficRouter {
    private Version live;

    public BlueGreenRouter(Version live) { this.live = live; }

    // Instant cutover: flip the switch, every request now goes to the other env.
    public void flip(Version target) { this.live = target; }

    @Override
    public RouteDecision route(int requestNumber) {
        return new RouteDecision(live, null, false);
    }

    @Override public String name() { return "Blue-Green(live=" + live + ")"; }
    @Override public String rollbackSpeed() {
        return "instant — flip the switch back to the other environment";
    }
}
