package com.bank.strategies.router;

import com.bank.strategies.model.RouteDecision;
import com.bank.strategies.model.Version;

// OLD serves the user; a COPY goes to NEW whose response is discarded.
public class ShadowRouter implements TrafficRouter {
    @Override
    public RouteDecision route(int requestNumber) {
        // User always gets OLD; NEW is exercised but its output is thrown away.
        return new RouteDecision(Version.OLD, Version.NEW, true);
    }

    @Override public String name() { return "Shadow"; }
    @Override public String rollbackSpeed() {
        return "n/a — users never see NEW, zero user risk";
    }
}
