package com.bank.strategies.service;

import com.bank.strategies.model.RouteDecision;
import com.bank.strategies.model.Version;
import com.bank.strategies.router.TrafficRouter;
import java.util.logging.Logger;

// Drives a stream of requests through a chosen router and reports the split.
public class ReleaseController {
    private static final Logger log = Logger.getLogger(ReleaseController.class.getName());

    public void run(TrafficRouter router, int totalRequests) {
        log.info(() -> "=== " + router.name() + " | rollback: " + router.rollbackSpeed() + " ===");
        int servedByNew = 0, mirrored = 0;
        for (int i = 0; i < totalRequests; i++) {
            RouteDecision d = router.route(i);
            if (d.getServedBy() == Version.NEW) servedByNew++;
            if (d.getMirroredTo() != null && d.isMirrorDiscarded()) mirrored++;
        }
        final int sn = servedByNew, m = mirrored;
        log.info(() -> "served by NEW (user-facing) = " + sn + "/" + totalRequests);
        if (m > 0) log.info(() -> "mirrored to NEW (discarded) = " + m + "/" + totalRequests);
    }
}
