package com.bank.strategies;

import com.bank.strategies.model.Version;
import com.bank.strategies.router.BlueGreenRouter;
import com.bank.strategies.router.CanaryRouter;
import com.bank.strategies.router.ShadowRouter;
import com.bank.strategies.service.ReleaseController;

public class StrategyDemo {
    public static void main(String[] args) {
        ReleaseController controller = new ReleaseController();
        int requests = 1000; // simulate 1000 transfer requests

        // Canary: 10% of real users hit NEW while we watch metrics.
        controller.run(new CanaryRouter(10), requests);

        // Blue-Green: flip all traffic to NEW instantly; revert is instant too.
        BlueGreenRouter bg = new BlueGreenRouter(Version.OLD);
        bg.flip(Version.NEW);
        controller.run(bg, requests);

        // Shadow: users stay on OLD; NEW processes copies and discards results.
        controller.run(new ShadowRouter(), requests);
    }
}
